// src/components/Login.js
import React from 'react';
import { GoogleAuthProvider, FacebookAuthProvider, signInWithPopup } from 'firebase/auth';
import { auth } from "../auth/firebase";

export default function Login() {
  const loginWithGoogle = async () => {
    const provider = new GoogleAuthProvider();
    try {
      const result = await signInWithPopup(auth, provider);
      console.log('Googleログイン成功:', result.user);
    } catch (error) {
      console.error('Googleログイン失敗:', error);
    }
  };

  const handleFacebookLogin = async () => {
    const provider = new FacebookAuthProvider();
    try {
      const result = await signInWithPopup(auth, provider);
      console.log("Facebookログイン成功:", result.user);
    } catch (error) {
      console.error("Facebookログインエラー:", error);
    }
  };

  return (
    <div className="p-4">
      <h2 className="text-lg font-bold mb-4">ログインしてください</h2>

      <button
        onClick={loginWithGoogle}
        className="bg-red-600 text-white px-4 py-2 rounded mb-2 block"
      >
        Googleでログイン
      </button>

      <button
        onClick={handleFacebookLogin}
        className="bg-blue-800 text-white px-4 py-2 rounded block"
      >
        Facebookでログイン
      </button>
    </div>
  );
}
