// src/components/App/index.js
import React from "react";
import { AuthProvider, useAuth } from "../AuthProvider";
import Login from "../Login";
import Dashboard from "../Dashboard";

const AppContent = () => {
  const { user } = useAuth();
  return user ? <Dashboard /> : <Login />;
};

const AppIndex = () => (
  <AuthProvider>
    <AppContent />
  </AuthProvider>
);

export default AppIndex;
